contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with inputs: caller (as address), encodedParameters, ownedBy
    // We cannot change msg.sender when calling c from this contract; msg.sender will be this contract.
    // To simulate operator vs non-operator, we rely on c.programOperators mapping which is public.
    // The test will first read current roundImplementation and alloSettings, then attempt create
    // and assert that if programOperators[this]==true then create either succeeds or reverts only due to other preconditions,
    // but if programOperators[this]==false then create must revert and state must be unchanged and no clone created.

    function run(bytes calldata encodedParameters, address ownedBy) public payable {
        require(true);

        // Read observables before the call
        address beforeRoundImpl = c.roundImplementation();
        address beforeAllo = c.alloSettings();
        bool isOperator = c.programOperators(address(this));

        bool reverted;
        address cloneAddress;
        // Attempt the state-changing call as a top-level statement
        try c.create(encodedParameters, ownedBy) returns (address addr) {
            reverted = false;
            cloneAddress = addr;
        } catch {
            reverted = true;
            cloneAddress = address(0);
        }

        // After-call observations
        address afterRoundImpl = c.roundImplementation();
        address afterAllo = c.alloSettings();
        // The general rule to assert:
        // If this contract is NOT a program operator, create MUST revert, must not have produced a non-zero clone address,
        // and must not change roundImplementation or alloSettings.
        // If this contract IS a program operator, we make no strong universal claim here (other preconditions may cause revert),
        // so we assert only the necessary implication for non-operators.
        assert(
            // If not operator then reverted && no clone && state unchanged
            isOperator || (
                reverted == true
                && cloneAddress == address(0)
                && afterRoundImpl == beforeRoundImpl
                && afterAllo == beforeAllo
            )
        );
    }

    receive() external payable {}
}

