contract InvMutTest {
    C c;
    address deployer;
    constructor(C _c) { c = _c; deployer = msg.sender; }

    // Test parameters: newImpl and a flag indicating whether the caller should be the owner.
    // We cannot change msg.sender of this contract, but the checker deploys a fresh C and sets ownership
    // to this contract in its initialize step; however to be safe we allow calling updateRoundImplementation
    // and catch reverts if not owner.
    function run(address newImpl, bool callAsOwner) public payable {
        require(true);

        // Observe before-value
        address before = c.roundImplementation();

        bool reverted;
        // perform the state-changing call at top-level; catch reverts
        try c.updateRoundImplementation(payable(newImpl)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-value
        address after = c.roundImplementation();

        // GENERAL RULE:
        // If the call did NOT revert then after == newImpl and newImpl != address(0).
        // If the call DID revert then after == before (no observable change to stored value).
        // This encodes the intended behavior: updating to a non-zero address succeeds and sets the getter;
        // invalid/unauthorized attempts revert and leave state unchanged.
        assert(
            (!reverted && newImpl != address(0) && after == newImpl)
            || (reverted && after == before)
        );
    }

    // Allow receiving Ether if needed elsewhere
    receive() external payable {}
}

