contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // param: newAllo is the address passed to updateAlloSettings
    // param: asOwner toggles whether this contract will act as owner (1) or not (0)
    function run(address newAllo, uint8 asOwner) public payable {
        require(asOwner <= 1, "asOwner must be 0 or 1");

        // Observe before value
        address before = c.alloSettings();

        bool reverted;
        // If we want this contract to be the owner, it must have been set as owner earlier by calling initialize and transferring ownership.
        // The checker deploys a fresh C and our contract is msg.sender for calls; to make this contract the owner we call c.initialize() via our contract.
        // c.initialize() is external and uses Initializable initializer; it sets owner to msg.sender. Call it top-level if desired.
        if (asOwner == 1) {
            // call initialize to become owner (top-level state-changing call)
            c.initialize();
        }

        // Now attempt the update, catching revert
        try c.updateAlloSettings(newAllo) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after value
        address after = c.alloSettings();

        // General rule:
        // - If the call reverted, alloSettings must be unchanged (after == before).
        // - If the call did not revert, alloSettings must equal newAllo and the caller must have been the owner (asOwner==1).
        assert(
            (reverted && after == before)
            || (!reverted && after == newAllo && asOwner == 1)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We take inputs that drive create: encodedParameters, ownedBy, and we also allow trying
    // to set programOperators mapping by using the fact that this test contract deployed c
    // so it can call c.updateRoundImplementation / updateAlloSettings only if it is owner.
    // However, per constraints the checker deploys a fresh c and this contract deployed it,
    // so this contract is the owner. We therefore allow the test to optionally set valid
    // roundImplementation and alloSettings before calling create.

    function run(bytes calldata encodedParameters, address ownedBy, address newRoundImpl, address newAlloSettings, bool setImpl, bool setSettings) public payable {
        require(true);

        // If requested, set roundImplementation and alloSettings as the owner
        if (setImpl) {
            // top-level state-changing call
            c.updateRoundImplementation(payable(newRoundImpl));
        }
        if (setSettings) {
            c.updateAlloSettings(newAlloSettings);
        }

        // Make caller a program operator so create can be called. The test contract itself
        // cannot modify programOperators (it's non-public), but the initial deployed c may
        // have programOperators[msg.sender] false. Since the checker will attempt to reach
        // the assert, we must handle both revert and success. We call create and record
        // whether it reverted and the returned address if any.
        bool reverted;
        address created;
        try c.create(encodedParameters, ownedBy) returns (address addr) {
            reverted = false;
            created = addr;
        } catch {
            reverted = true;
            created = address(0);
        }

        // Read observable public state after the call
        address implAfter = c.roundImplementation();
        address settingsAfter = c.alloSettings();

        // General rule (single assert):
        // If create succeeded (not reverted) then it must return a non-zero address and that address
        // must be a contract (code.length>0). Additionally, the create call itself does not change
        // the stored roundImplementation or alloSettings (they remain equal to what they were set to via public setters earlier in this transaction or previously).
        // We express that by requiring that if not reverted then created != address(0) and extcodesize(created) > 0,
        // and regardless of revert flag the stored values equal the values after we optionally set them.

        // To check extcodesize of the created address we use assembly.
        uint256 codeSize;
        if (!reverted && created != address(0)) {
            assembly { codeSize := extcodesize(created) }
        }

        // The assert combines these properties. Note: implAfter and settingsAfter are the authoritative
        // public getters; we ensure the values equal what update calls set earlier by reasoning that
        // update* are the only public setters for them and we invoked them above when requested.
        assert(
            (reverted || (created != address(0) && codeSize > 0))
            && (
                // If we requested setImpl then implAfter must equal newRoundImpl, otherwise it may be any value but
                // it must equal the public getter we just read (tautologically true) — to make the assertion meaningful
                // we require that implAfter equals newRoundImpl when setImpl is true.
                (!setImpl || implAfter == newRoundImpl)
            )
            && (
                // Similarly for settings
                (!setSettings || settingsAfter == newAlloSettings)
            )
        );
    }

    receive() external payable {}
}

