        bool reverted;
        address created;
        try c.create(encodedParameters, ownedBy) returns (address addr) {
            reverted = false;
            created = addr;
        } catch {
            reverted = true;
            created = address(0);
        }

        // Read public getters after the calls
        address implAfter = c.roundImplementation();
        address settingsAfter = c.alloSettings();

        // Determine code size of the created address if create did not revert and returned non-zero.
