contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry performing the property check
    function run(address encodedTarget, address ownedBy, bool makeOperator) public payable {
        // precondition: use arbitrary inputs; ensure this contract has some balance if we attempt value (we don't send value here)
        require(true);

        // Snapshot observable state before the call
        address beforeRoundImplementation = c.roundImplementation();
        address beforeAlloSettings = c.alloSettings();

        // Optionally set programOperators mapping by calling on c as owner if this contract is owner.
        // We cannot assume deployer is owner; however the test can try to set programOperators by calling create only.
        // We will attempt the create call and record whether it reverted.

        bool reverted;
        address returnedAddress = address(0);
        // Make the deciding call: onlyProgramOperator may revert if caller not operator
        try c.create(abi.encode(encodedTarget), ownedBy) returns (address addr) {
            reverted = false;
            returnedAddress = addr;
        } catch {
            reverted = true;
        }

        // After-call observations
        address afterRoundImplementation = c.roundImplementation();
        address afterAlloSettings = c.alloSettings();
        uint256 factoryBalance = address(c).balance;

        // General rule (single assert):
        // - The factory's roundImplementation and alloSettings are never modified by create (only owner functions can change them).
        // - If create succeeded (not reverted) it must return a non-zero address.
        // - If create reverted, returnedAddress is zero.
        assert(
            afterRoundImplementation == beforeRoundImplementation
            && afterAlloSettings == beforeAlloSettings
            && (reverted ? returnedAddress == address(0) : returnedAddress != address(0))
        );
    }

    // receive to accept Ether if needed by the environment
    receive() external payable {}
}

