    //  newImpl: address to pass to updateRoundImplementation
    function run(bool callerIsOwner, address newImpl) public payable {
        require(true);

        // Observe before-values
        address before = c.roundImplementation();

        bool didRevert;
        // We must call updateRoundImplementation as this contract (msg.sender == this)
        // The checker deploys c with this contract as deployer, so this contract should be owner. However to be general,
        // we detect whether the call reverts or not.
        try c.updateRoundImplementation(payable(newImpl)) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        address after = c.roundImplementation();

        // Rule to assert:
        // - If the call succeeded then newImpl must be non-zero and after == newImpl.
        // - If the call reverted then after must equal before (no state change).
        // This also captures that non-owners cannot change the implementation (their attempts revert and state unchanged).
        assert(
            (didRevert && after == before) || (!didRevert && newImpl != address(0) && after == newImpl)
        );
    }

