contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Attempt to check that non-program-operators cannot successfully call create.
    // Parameters:
    //  encodedParameters: arbitrary bytes forwarded to create
    //  ownedBy: address forwarded to create
    //  makeOperator: if true, this test will first set programOperators[address(this)] = true by calling a public function that exists on C? C exposes mapping programOperators as public, but no setter; however C has onlyOwner modifiers for update functions. The deployer of C is the test harness deployer, but the checker deploys a fresh c and then deploys this test with c passed in; the test contract is NOT the owner. So we cannot call owner-only functions. Instead we will observe programOperators flag and assert that whenever create succeeds, programOperators[address(this)] was true (as observed before the call).
    function run(bytes calldata encodedParameters, address ownedBy) public payable {
        require(true);

        // Observe whether this contract is currently a program operator
        bool wasOperator = c.programOperators(address(this));

        // Ensure roundImplementation and alloSettings are set on c by not assuming: calls may revert if they are zero.
        // We will attempt the create call and record if it reverts.
        bool didRevert;
        address cloneAddr;
        try c.create(encodedParameters, ownedBy) {
            didRevert = false;
            // if it succeeded, read returned clone via another call: create returns address but try-without-return cannot capture it; instead read last emitted RoundCreated? Not available. However create returns the clone address, but try c.create(...) { } does not capture return. To observe success we only need didRevert == false.
        } catch {
            didRevert = true;
        }

        // The general rule: if create succeeded (didRevert == false) then this contract must have been a program operator before the call.
        assert(didRevert || wasOperator);
    }

    receive() external payable {}
}
